CREATE POLICY "property photos readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'property-photos');
CREATE POLICY "landlord uploads own photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'property-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "landlord updates own photos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'property-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "landlord deletes own photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'property-photos' AND (storage.foldername(name))[1] = auth.uid()::text);